Contract AutomatedTellerMachineSystem::checkBalance(): Real {

            precondition:
          self.InputCard.oclIsUndefined() = false and self.PasswordValidated = true and self.CardIDValidated = true and BankCard.allInstance()->includes(self.InputCard) and self.InputCard.CardStatus = BankCard::NORMAL

            postcondition:
          result = self.InputCard.Balance

        }

Contract ManageBankCardCRUDService::createBankCard(cardid:Integer,cardstatus:CardStatus[NORMAL|SUSPEND|CANCEL],catalog:CardCatalog[CREDIT|DEPOSIT],password:Integer,balance:Real): Boolean {

            precondition:
          BankCard.allInstance()->excludes(BankCard.allInstance()->any(o:BankCard | o.CardID = cardid)) and password > 0 and balance >= 0

            postcondition:
          let newCard:BankCard in newCard.oclIsNew() and BankCard.allInstance()->includes(newCard) and newCard.CardID = cardid and newCard.CardStatus = cardstatus and newCard.Catalog = catalog and newCard.Password = password and newCard.Balance = balance and result = true

        }

Contract ManageSupplierCRUDService::createSupplier(id:Integer,name:String): Boolean {

            precondition:
          Supplier.allInstance()->any(o | o.Id = id).oclIsUndefined() = true

            postcondition:
          let supplier:Supplier in supplier.oclIsNew() and supplier.Id = id and supplier.Name = name and Supplier.allInstance()->includes(supplier) and result = true

        }

Contract CoCoMEOrderProducts::placeOrder(): Boolean {

            precondition:
          self.CurrentOrderProduct.oclIsUndefined() = false and OrderProduct.allInstance()->includes(self.CurrentOrderProduct) and self.CurrentOrderProduct.OrderStatus = OrderStatus::NEW and self.CurrentOrderProduct.ContainedEntries.isEmpty() = false

            postcondition:
          self.CurrentOrderProduct.OrderStatus = OrderStatus::REQUESTED and result = true

        }

