Contract ProcessSaleService::makeCashPayment(amount:Real): Boolean {

            precondition:
          amount > 0 and PaymentMethod::CASH = PaymentMethod::CASH

            postcondition:
          let payment:CashPayment in payment.oclIsNew() and Payment.allInstance()->includes(payment) and payment.AmountTendered = amount and payment.Balance = amount and result = true

